import torch

def assert_world_round_trip(geometry, world_xyz, *, atol_mm):
    """Test an injected geometry adapter in physical millimeters."""
    if atol_mm <= 0:
        raise ValueError("atol_mm must be positive")
    world = torch.as_tensor(world_xyz, dtype=torch.float64)
    if world.shape != (3,):
        raise ValueError("world_xyz must contain x, y, z")
    continuous_index = torch.as_tensor(
        geometry.world_to_continuous_index(world.tolist()),
        dtype=torch.float64,
    )
    recovered = torch.as_tensor(
        geometry.continuous_index_to_world(continuous_index.tolist()),
        dtype=torch.float64,
    )
    torch.testing.assert_close(
        recovered, world, rtol=0.0, atol=float(atol_mm),
    )
    return continuous_index

import math
from numbers import Integral
import torch

def validate_sample(sample, expected_shape):
    """Raise explicit errors so checks survive `python -O`."""
    image = sample["image"]
    if tuple(image.shape) != tuple(expected_shape):
        raise ValueError(
            f"crop shape {tuple(image.shape)} != {tuple(expected_shape)}"
        )
    if image.dtype != torch.float32:
        raise TypeError(f"expected float32 image, got {image.dtype}")
    if not bool(torch.isfinite(image).all()):
        raise ValueError("image contains a non-finite value")

    label = sample["label"]
    if isinstance(label, bool) or not isinstance(label, Integral) or label not in (0, 1):
        raise ValueError(f"invalid binary label: {label!r}")
    series_uid = sample["series_uid"]
    if not isinstance(series_uid, str) or not series_uid:
        raise ValueError("series_uid must be a non-empty string")
    center = sample["center_xyz"]
    if len(center) != 3 or not all(math.isfinite(float(x)) for x in center):
        raise ValueError("center_xyz must contain three finite values")
    return sample

from collections.abc import Callable, Sequence
from typing import Any, TypedDict
import torch
from torch.utils import data

class CandidateSample(TypedDict):
    image: torch.Tensor
    label: int
    series_uid: str
    center_xyz: tuple[float, float, float]

class CandidateDataset(data.Dataset):
    def __init__(
        self,
        candidates: Sequence[Any],
        load_candidate: Callable[[Any], CandidateSample],
        validate: Callable[[CandidateSample, tuple[int, ...]], CandidateSample],
        crop_shape: tuple[int, ...],
    ):
        self.candidates = tuple(candidates)
        self.load_candidate = load_candidate
        self.validate = validate
        self.crop_shape = tuple(crop_shape)

    def __len__(self):
        return len(self.candidates)

    def __getitem__(self, index) -> CandidateSample:
        sample = self.load_candidate(self.candidates[index])
        return self.validate(sample, self.crop_shape)
